const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'y' },
      { kind: 'text', payload: 'O' },
      { kind: 'text', payload: 'P(-3,2)' },
      { kind: 'text', payload: '第二象限' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var xMin = -5.5, xMax = 5.5, yMin = -4.5, yMax = 4.5;
    var scale = Math.min((W - 120) / (xMax - xMin), (H - 100) / (yMax - yMin));
    if (!isFinite(scale) || scale <= 0) scale = Math.min(W, H) / 12;
    var ox = W / 2;
    var oy = H / 2;
    function sx(x) { return ox + x * scale; }
    function sy(y) { return oy - y * scale; }
    function line(pts) {
      try {
        return visualSdk.polyline(pts);
      } catch (e) {
        var objPts = [];
        for (var i = 0; i < pts.length; i++) objPts.push({ x: pts[i][0], y: pts[i][1] });
        return visualSdk.polyline(objPts);
      }
    }
    function addCommands(target, cmds) {
      for (var i = 0; i < cmds.length; i++) target.push(cmds[i]);
      return target;
    }
    function dashed(x1, y1, x2, y2, dash, gap) {
      var dx = x2 - x1, dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) return [];
      var ux = dx / len, uy = dy / len;
      var cmds = [];
      var d = 0;
      while (d < len) {
        var e = Math.min(d + dash, len);
        addCommands(cmds, line([[x1 + ux * d, y1 + uy * d], [x1 + ux * e, y1 + uy * e]]));
        d = e + gap;
      }
      return cmds;
    }

    var axisCmds = [];
    addCommands(axisCmds, line([[sx(-5.2), sy(0)], [sx(5.2), sy(0)]]));
    addCommands(axisCmds, line([[sx(0), sy(-4.2)], [sx(0), sy(4.2)]]));

    var tickCmds = [];
    var t;
    for (t = -5; t <= 5; t++) {
      if (t === 0) continue;
      addCommands(tickCmds, line([[sx(t), sy(0) - 4], [sx(t), sy(0) + 4]]));
    }
    for (t = -4; t <= 4; t++) {
      if (t === 0) continue;
      addCommands(tickCmds, line([[sx(0) - 4, sy(t)], [sx(0) + 4, sy(t)]]));
    }

    var px = sx(-3), py = sy(2);
    var xFootX = sx(-3), xFootY = sy(0);
    var yFootX = sx(0), yFootY = sy(2);
    var dashCmds = [];
    addCommands(dashCmds, dashed(px, py, xFootX, xFootY, 6, 4));
    addCommands(dashCmds, dashed(px, py, yFootX, yFootY, 6, 4));

    var pointCmds = visualSdk.circle(px, py, 4.2);
    var foot1Cmds = visualSdk.circle(xFootX, xFootY, 3);
    var foot2Cmds = visualSdk.circle(yFootX, yFootY, 3);

    return {
      schemaVersion: 1,
      sceneId: 'quadrant-point-p',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'axis', commands: axisCmds },
        { id: 'ticks', commands: tickCmds },
        { id: 'dash', commands: dashCmds },
        { id: 'point', commands: pointCmds },
        { id: 'foot1', commands: foot1Cmds },
        { id: 'foot2', commands: foot2Cmds }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'axis', fill: 'none', stroke: { width: 2 } },
        { type: 'path', pathId: 'ticks', fill: 'none', stroke: { width: 1.5 } },
        { type: 'path', pathId: 'dash', fill: 'none', stroke: { width: 1.5 } },
        { type: 'path', pathId: 'foot1', fill: '#ffffff', stroke: { width: 1.2 } },
        { type: 'path', pathId: 'foot2', fill: '#ffffff', stroke: { width: 1.2 } },
        { type: 'path', pathId: 'point', fill: '#d94841', stroke: { width: 1.2 } },
        { type: 'label', contentId: 'c0', anchor: { x: sx(5.28), y: sy(0) }, hAlign: 'left', vAlign: 'middle', color: '#26354a' },
        { type: 'label', contentId: 'c1', anchor: { x: sx(0), y: sy(4.28) }, hAlign: 'center', vAlign: 'bottom', color: '#26354a' },
        { type: 'label', contentId: 'c2', anchor: { x: sx(0) - 8, y: sy(0) + 8 }, hAlign: 'right', vAlign: 'top', color: '#26354a' },
        { type: 'label', contentId: 'c3', anchor: { x: px + 9, y: py - 9 }, hAlign: 'left', vAlign: 'bottom', color: '#26354a' },
        { type: 'label', contentId: 'c4', anchor: { x: sx(-4.2), y: sy(3.55) }, hAlign: 'center', vAlign: 'middle', color: '#26354a' }
      ] }
    };
  }
};
